import{_ as t,o,c as a,a2 as i}from"./chunks/framework.DBSoX6Zw.js";const u=JSON.parse('{"title":"Architecture — CLI Client (client/)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/client.md","filePath":"architecture/client.md"}'),n={name:"architecture/client.md"};function r(s,e,c,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture-—-cli-client-client" tabindex="-1">Architecture — CLI Client (<code>client/</code>) <a class="header-anchor" href="#architecture-—-cli-client-client" aria-label="Permalink to &quot;Architecture — CLI Client (`client/`)&quot;">​</a></h1><blockquote><p>The Plik command-line client. For system-wide overview, see the root <a href="./system.html">ARCHITECTURE.md</a>.</p></blockquote><hr><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client/</span></span>\n<span class="line"><span>├── plik.go        ← main CLI logic (docopt-based argument parsing + upload flow)</span></span>\n<span class="line"><span>├── mcp.go         ← MCP (Model Context Protocol) server over stdio for AI assistants</span></span>\n<span class="line"><span>├── config.go      ← configuration loading (.plikrc)</span></span>\n<span class="line"><span>├── login.go       ← CLI device auth flow (--login)</span></span>\n<span class="line"><span>├── progress.go    ← upload progress bar</span></span>\n<span class="line"><span>├── update.go      ← self-update mechanism</span></span>\n<span class="line"><span>├── archive/       ← archive backends (tar, zip)</span></span>\n<span class="line"><span>├── crypto/        ← crypto backends (openssl, pgp)</span></span>\n<span class="line"><span>├── .plikrc        ← example client configuration</span></span>\n<span class="line"><span>├── plik.sh        ← bash upload wrapper</span></span>\n<span class="line"><span>├── test.sh        ← CLI integration tests</span></span>\n<span class="line"><span>├── test_downgrade.sh  ← client version downgrade tests</span></span>\n<span class="line"><span>└── test_upgrade.sh    ← client version upgrade tests</span></span></code></pre></div><hr><h2 id="key-components" tabindex="-1">Key Components <a class="header-anchor" href="#key-components" aria-label="Permalink to &quot;Key Components&quot;">​</a></h2><h3 id="cli-entry-point-plik-go" tabindex="-1">CLI Entry Point (<code>plik.go</code>) <a class="header-anchor" href="#cli-entry-point-plik-go" aria-label="Permalink to &quot;CLI Entry Point (`plik.go`)&quot;">​</a></h3><p>Uses <a href="https://github.com/docopt/docopt-go" target="_blank" rel="noreferrer">docopt-go</a> for argument parsing. The main flow:</p><ol><li>Parse CLI args (file paths, options like <code>--oneshot</code>, <code>--stream</code>, <code>--ttl</code>, etc.)</li><li>Load config from <code>.plikrc</code> (or <code>PLIKRC</code> env var)</li><li>Handle special modes: <code>--mcp</code> (MCP server), <code>--login</code> (device auth), <code>--update</code> (self-update), <code>--version</code></li><li>Create upload via the Go library (<code>plik/</code>)</li><li>Add files (with optional archive/encrypt preprocessing)</li><li>Upload files with progress bars</li><li>Print download URLs</li></ol><h3 id="configuration-config-go" tabindex="-1">Configuration (<code>config.go</code>) <a class="header-anchor" href="#configuration-config-go" aria-label="Permalink to &quot;Configuration (`config.go`)&quot;">​</a></h3><p>Config is a TOML file loaded from (in order):</p><ol><li><code>PLIKRC</code> environment variable</li><li><code>~/.plikrc</code></li><li><code>/etc/plik/plikrc</code></li></ol><p>Key config fields: <code>URL</code> (server), <code>Token</code> (user authentication token), archive/crypto defaults.</p><h3 id="cli-login-login-go" tabindex="-1">CLI Login (<code>login.go</code>) <a class="header-anchor" href="#cli-login-login-go" aria-label="Permalink to &quot;CLI Login (`login.go`)&quot;">​</a></h3><p>Implements a device authorization flow for CLI authentication:</p><ol><li>POST <code>/auth/cli/init</code> with hostname → receives a code, secret, and verification URL</li><li>Opens verification URL in user&#39;s browser (best-effort)</li><li>Polls POST <code>/auth/cli/poll</code> with code + secret every 2s</li><li>On approval, saves the token to <code>~/.plikrc</code> and exits</li></ol><p>Triggered by <code>--login</code> flag or interactively during first-run when auth is enabled/forced.</p><h3 id="archive-backends-archive" tabindex="-1">Archive Backends (<code>archive/</code>) <a class="header-anchor" href="#archive-backends-archive" aria-label="Permalink to &quot;Archive Backends (`archive/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Backend</th><th>Description</th></tr></thead><tbody><tr><td><code>tar</code></td><td>Create tar archives with compression (gzip, bzip2, xz, lzip, lzma, lzop)</td></tr><tr><td><code>zip</code></td><td>Create zip archives</td></tr></tbody></table><p>Archives wrap multiple files/directories into a single upload file.</p><h3 id="crypto-backends-crypto" tabindex="-1">Crypto Backends (<code>crypto/</code>) <a class="header-anchor" href="#crypto-backends-crypto" aria-label="Permalink to &quot;Crypto Backends (`crypto/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Backend</th><th>Description</th></tr></thead><tbody><tr><td><code>openssl</code></td><td>Symmetric encryption via OpenSSL CLI (configurable cipher)</td></tr><tr><td><code>pgp</code></td><td>Asymmetric encryption via GPG/PGP (recipient-based)</td></tr><tr><td><code>age</code></td><td>Modern encryption via <a href="https://age-encryption.org/" target="_blank" rel="noreferrer">age</a>. Supports passphrase, X25519, SSH recipients (<code>@github_user</code>, URL, raw key), and SSH host key scanning (<code>ssh://hostname</code>). <strong>Default backend.</strong> Sets <code>upload.E2EE = &quot;age&quot;</code> for webapp interop (passphrase mode only)</td></tr></tbody></table><p>Encryption wraps the file data stream before upload.</p><p>When the <code>age</code> backend is used, the upload is flagged as E2EE (<code>upload.E2EE = &quot;age&quot;</code>). This tells the webapp to prompt for a passphrase on download and decrypt client-side. A cryptographically-secure passphrase is auto-generated when none is provided.</p><h3 id="self-update-update-go" tabindex="-1">Self-Update (<code>update.go</code>) <a class="header-anchor" href="#self-update-update-go" aria-label="Permalink to &quot;Self-Update (`update.go`)&quot;">​</a></h3><p>The client can update itself by downloading the latest matching binary from the configured Plik server. It compares versions and replaces the current binary in-place.</p><h3 id="mcp-server-mcp-go" tabindex="-1">MCP Server (<code>mcp.go</code>) <a class="header-anchor" href="#mcp-server-mcp-go" aria-label="Permalink to &quot;MCP Server (`mcp.go`)&quot;">​</a></h3><p>Implements a local <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a> server over stdio, enabling AI coding assistants (Cursor, VS Code Copilot, etc.) to upload files via Plik. Activated by <code>plik --mcp</code>.</p><p>Uses the official <a href="https://github.com/modelcontextprotocol/go-sdk" target="_blank" rel="noreferrer">Go MCP SDK</a> (<code>mcp.StdioTransport</code>) and the <code>plik/</code> Go library for uploads.</p><p><strong>Tools:</strong></p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>upload_text</code></td><td>Upload inline text content as a named file</td></tr><tr><td><code>upload_file</code></td><td>Upload a single file by path</td></tr><tr><td><code>upload_files</code></td><td>Upload multiple files by paths in a single upload</td></tr><tr><td><code>server_info</code></td><td>Get server version, config, and capabilities</td></tr></tbody></table><p><strong>Prompts:</strong> <code>upload_guide</code></p><p>All upload tools use <code>plik.UploadParams</code> via struct embedding and return <code>UploadWithURL</code> — the standard <code>common.Upload</code> metadata enriched with computed URLs.</p><hr><h2 id="integration-tests" tabindex="-1">Integration Tests <a class="header-anchor" href="#integration-tests" aria-label="Permalink to &quot;Integration Tests&quot;">​</a></h2><ul><li><code>test.sh</code> — comprehensive CLI integration tests (requires a running server)</li><li><code>test_upgrade.sh</code> / <code>test_downgrade.sh</code> — version compatibility tests (stale, unused since ~2021)</li></ul>',37)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
